"use strict";(globalThis.webpackChunkwebsite=globalThis.webpackChunkwebsite||[]).push([[8065],{1380(e,r,s){s.r(r),s.d(r,{assets:()=>o,contentTitle:()=>l,default:()=>c,frontMatter:()=>a,metadata:()=>n,toc:()=>u});const n=JSON.parse('{"id":"camera2/understanding-smartphone-cameras","title":"Chapitre 2 : Comprendre les cam\xe9ras des smartphones","description":"Explorez le mat\xe9riel du module cam\xe9ra \xe0 l\'int\xe9rieur de chaque smartphone : l\'objectif, le capteur d\'image, le processeur ISP, la diff\xe9rence entre RAW et JPEG, les conceptions multi-cam\xe9ras et le voyage complet des photons \xe0 une photo stock\xe9e.","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/camera2/understanding-smartphone-cameras.md","sourceDirName":"camera2","slug":"/camera2/understanding-smartphone-cameras","permalink":"/AndroidCameraParameters/fr/camera2/understanding-smartphone-cameras","draft":false,"unlisted":false,"editUrl":"https://github.com/zoozooll/AndroidCameraParameters/tree/main/website/docs/camera2/understanding-smartphone-cameras.md","tags":[],"version":"current","sidebarPosition":2,"frontMatter":{"sidebar_position":2,"title":"Chapitre 2 : Comprendre les cam\xe9ras des smartphones","description":"Explorez le mat\xe9riel du module cam\xe9ra \xe0 l\'int\xe9rieur de chaque smartphone : l\'objectif, le capteur d\'image, le processeur ISP, la diff\xe9rence entre RAW et JPEG, les conceptions multi-cam\xe9ras et le voyage complet des photons \xe0 une photo stock\xe9e.","keywords":["cam\xe9ra smartphone","module cam\xe9ra","objectif cam\xe9ra","capteur d\'image","ISP","RAW vs JPEG","multi-cam\xe9ra"]},"sidebar":"tutorialSidebar","previous":{"title":"Chapitre 1 : Bienvenue dans Android Camera2","permalink":"/AndroidCameraParameters/fr/camera2/welcome-to-android-camera2"},"next":{"title":"Chapitre 3 : La photographie moderne sur smartphone","permalink":"/AndroidCameraParameters/fr/camera2/what-can-modern-smartphone-cameras-do"}}');var i=s(4848),t=s(8453);const a={sidebar_position:2,title:"Chapitre 2 : Comprendre les cam\xe9ras des smartphones",description:"Explorez le mat\xe9riel du module cam\xe9ra \xe0 l'int\xe9rieur de chaque smartphone : l'objectif, le capteur d'image, le processeur ISP, la diff\xe9rence entre RAW et JPEG, les conceptions multi-cam\xe9ras et le voyage complet des photons \xe0 une photo stock\xe9e.",keywords:["cam\xe9ra smartphone","module cam\xe9ra","objectif cam\xe9ra","capteur d'image","ISP","RAW vs JPEG","multi-cam\xe9ra"]},l="Chapitre 2 : Comprendre les cam\xe9ras des smartphones",o={},u=[{value:"Le module cam\xe9ra : Un assemblage optique scell\xe9",id:"le-module-cam\xe9ra--un-assemblage-optique-scell\xe9",level:2},{value:"L&#39;objectif : Distance focale, ouverture et stabilisation",id:"lobjectif--distance-focale-ouverture-et-stabilisation",level:2},{value:"Distance focale et \xe9quivalence plein format",id:"distance-focale-et-\xe9quivalence-plein-format",level:3},{value:"Ouverture",id:"ouverture",level:3},{value:"Stabilisation optique de l&#39;image (OIS)",id:"stabilisation-optique-de-limage-ois",level:3},{value:"Le capteur d&#39;image : L\xe0 o\xf9 la lumi\xe8re devient \xe9lectricit\xe9",id:"le-capteur-dimage--l\xe0-o\xf9-la-lumi\xe8re-devient-\xe9lectricit\xe9",level:2},{value:"Taille des pixels et m\xe9gapixels",id:"taille-des-pixels-et-m\xe9gapixels",level:3},{value:"Classifications de la taille du capteur",id:"classifications-de-la-taille-du-capteur",level:3},{value:"La matrice de filtres color\xe9s Bayer (CFA)",id:"la-matrice-de-filtres-color\xe9s-bayer-cfa",level:3},{value:"Obturateur roulant vs obturateur global",id:"obturateur-roulant-vs-obturateur-global",level:3},{value:"L&#39;ISP : Processeur de signal d&#39;image",id:"lisp--processeur-de-signal-dimage",level:2},{value:"RAW vs JPEG : Deux chemins du capteur au stockage",id:"raw-vs-jpeg--deux-chemins-du-capteur-au-stockage",level:2},{value:"Format RAW",id:"format-raw",level:3},{value:"Format JPEG",id:"format-jpeg",level:3},{value:"Tableau de comparaison : RAW vs JPEG",id:"tableau-de-comparaison--raw-vs-jpeg",level:3},{value:"T\xe9l\xe9phones multi-cam\xe9ras : Pourquoi pas un seul zoom g\xe9ant ?",id:"t\xe9l\xe9phones-multi-cam\xe9ras--pourquoi-pas-un-seul-zoom-g\xe9ant-",level:2},{value:"Le voyage complet : Du photon \xe0 la photo enregistr\xe9e, milliseconde par milliseconde",id:"le-voyage-complet--du-photon-\xe0-la-photo-enregistr\xe9e-milliseconde-par-milliseconde",level:2},{value:"R\xe9sum\xe9",id:"r\xe9sum\xe9",level:2},{value:"Et ensuite ?",id:"et-ensuite-",level:2}];function d(e){const r={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,t.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(r.header,{children:(0,i.jsx)(r.h1,{id:"chapitre-2--comprendre-les-cam\xe9ras-des-smartphones",children:"Chapitre 2 : Comprendre les cam\xe9ras des smartphones"})}),"\n",(0,i.jsx)(r.p,{children:"Avant d'\xe9crire une seule ligne de code pour l'API Camera2, vous devez comprendre le mat\xe9riel physique que votre code va commander. Une cam\xe9ra de smartphone n'est pas seulement \"un objectif point\xe9 vers un capteur\". C'est un ensemble scell\xe9, int\xe9gr\xe9 de mani\xe8re compacte et con\xe7u avec pr\xe9cision, contenant des optiques, des actionneurs, des filtres, des semi-conducteurs et des bus de donn\xe9es \xe0 haute vitesse. Ce chapitre explique chaque composant, du verre qui capte la lumi\xe8re en premier \xe0 la puce de m\xe9moire flash o\xf9 votre photo finale est stock\xe9e."}),"\n",(0,i.jsxs)(r.p,{children:["L'objectif de ce chapitre est de construire un mod\xe8le mental du pipeline de la cam\xe9ra en tant que syst\xe8me physique. Lorsque les chapitres suivants vous demanderont de configurer une requ\xeate de capture avec ",(0,i.jsx)(r.code,{children:"CONTROL_AE_TARGET_FPS_RANGE"})," ou ",(0,i.jsx)(r.code,{children:"SENSOR_SENSITIVITY"}),", vous comprendrez exactement quelle pi\xe8ce mat\xe9rielle ces param\xe8tres affectent et pourquoi les valeurs sont importantes."]}),"\n",(0,i.jsx)(r.h2,{id:"le-module-cam\xe9ra--un-assemblage-optique-scell\xe9",children:"Le module cam\xe9ra : Un assemblage optique scell\xe9"}),"\n",(0,i.jsx)(r.p,{children:"Lorsque vous regardez l'arri\xe8re d'un t\xe9l\xe9phone phare moderne \u2014 imaginez un Pixel 10 ou un Galaxy S26 Ultra \u2014 vous voyez un \xeelot rectangulaire sur\xe9lev\xe9 d\xe9passant de 2 \xe0 4 millim\xe8tres de la vitre arri\xe8re. Cet \xeelot n'est pas une seule cam\xe9ra. Un \xeelot rectangulaire abrite trois modules circulaires distincts : le plus grand en bas est le grand-angle principal, un plus petit au-dessus est le t\xe9l\xe9objectif p\xe9riscope 3\xd7, et celui de taille moyenne \xe0 gauche est l'ultra-grand-angle 0,5\xd7. Chaque \"bosse\" circulaire \xe0 l'int\xe9rieur de cet \xeelot est un module cam\xe9ra complet et ind\xe9pendant."}),"\n",(0,i.jsx)(r.p,{children:"Un module cam\xe9ra est une unit\xe9 scell\xe9e herm\xe9tiquement, fabriqu\xe9e dans une salle blanche sans poussi\xe8re. Il contient, empil\xe9s dans l'ordre de l'ext\xe9rieur vers l'int\xe9rieur :"}),"\n",(0,i.jsxs)(r.ol,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Vitre de protection"})," : Une fen\xeatre en saphir r\xe9sistant aux rayures ou en Gorilla Glass qui scelle le module et emp\xeache la poussi\xe8re d'entrer."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Barillet d'objectif"})," : Un empilement cylindrique de 4 \xe0 6 lentilles individuelles en verre (ou parfois en plastique asph\xe9rique), maintenues en alignement pr\xe9cis par de fines entretoises en plastique."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Moteur \xe0 bobine mobile (VCM)"})," : Un actionneur \xe9lectromagn\xe9tique qui d\xe9place l'ensemble du barillet d'objectif vers l'avant ou vers l'arri\xe8re le long de l'axe optique par fractions de millim\xe8tre pour r\xe9aliser la mise au point automatique. Certains VCM haut de gamme peuvent \xe9galement d\xe9placer l'objectif perpendiculairement \xe0 l'axe pour la stabilisation optique de l'image (OIS)."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Filtre anti-infrarouge (IR)"})," : Une fine plaquette de verre rev\xeatue plac\xe9e directement devant le capteur. Elle bloque la lumi\xe8re infrarouge (\xe0 laquelle le capteur en silicium est sensible mais pas l'\u0153il humain) afin que les couleurs enregistr\xe9es correspondent \xe0 ce que les humains per\xe7oivent."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Puce du capteur"})," : La puce du capteur d'image CMOS en silicium elle-m\xeame, reli\xe9e par des fils \xe0 un substrat. La matrice de pixels actifs est orient\xe9e vers le haut, vers l'objectif."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Circuit imprim\xe9 flexible (FPC)"})," : Un c\xe2ble ruban fin et pliable qui transporte l'alimentation, la masse, les signaux de commande (I2C) et les donn\xe9es d'image \xe0 haute vitesse (MIPI CSI-2) du module vers la carte m\xe8re du t\xe9l\xe9phone."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Connecteur carte \xe0 carte"})," : Une minuscule prise haute densit\xe9 \xe0 l'extr\xe9mit\xe9 du FPC qui s'enclenche dans un r\xe9ceptacle correspondant sur le PCB principal du t\xe9l\xe9phone."]}),"\n"]}),"\n",(0,i.jsx)(r.p,{children:"L'ensemble de l'assemblage \u2014 de la vitre de protection au connecteur \u2014 mesure g\xe9n\xe9ralement de 5 \xe0 8 millim\xe8tres d'\xe9paisseur pour une cam\xe9ra arri\xe8re conventionnelle, et de 10 \xe0 14 millim\xe8tres de long (\xe0 l'int\xe9rieur du t\xe9l\xe9phone, orient\xe9 horizontalement) pour un t\xe9l\xe9objectif p\xe9riscope. Les modules sont calibr\xe9s individuellement en usine : l'alignement de l'objectif, l'inclinaison du capteur, l'ombrage des couleurs et la position de mise au point \xe0 l'infini sont tous mesur\xe9s et stock\xe9s dans une m\xe9moire programmable une seule fois (OTP) sur le module lui-m\xeame. L'API Camera2 lit ces donn\xe9es de calibration au d\xe9marrage de l'appareil afin que votre application n'ait pas \xe0 tenir compte des variations de fabrication d'une unit\xe9 \xe0 l'autre."}),"\n",(0,i.jsx)(r.h2,{id:"lobjectif--distance-focale-ouverture-et-stabilisation",children:"L'objectif : Distance focale, ouverture et stabilisation"}),"\n",(0,i.jsx)(r.p,{children:"L'objectif est le premier composant que la lumi\xe8re rencontre. Son r\xf4le est de courber les rayons lumineux entrants afin qu'ils convergent en une image nette exactement sur le plan du capteur d'image."}),"\n",(0,i.jsx)(r.h3,{id:"distance-focale-et-\xe9quivalence-plein-format",children:"Distance focale et \xe9quivalence plein format"}),"\n",(0,i.jsxs)(r.p,{children:["La distance focale d\xe9termine le champ de vision (quelle partie de la sc\xe8ne entre dans le cadre) et le grossissement (quelle taille les sujets \xe9loign\xe9s apparaissent). Les sp\xe9cifications des cam\xe9ras de smartphone annoncent toujours des ",(0,i.jsx)(r.strong,{children:"distances focales \xe9quivalentes plein format"}),". Il s'agit d'une convention qui normalise les diff\xe9rentes tailles de capteurs afin que les consommateurs puissent comparer ce qui est comparable. Un capteur plein format est de la taille 36 mm \xd7 24 mm historiquement utilis\xe9e dans les appareils photo reflex argentiques 35 mm."]}),"\n",(0,i.jsx)(r.p,{children:"Distances focales \xe9quivalentes plein format courantes sur les smartphones :"}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"10\u201318 mm (Ultra-grand-angle)"})," : Champ de vision diagonal de 100\xb0 \xe0 130\xb0. Utilis\xe9 pour les paysages, l'architecture, les selfies de groupe et les gros plans macro."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"22\u201328 mm (Grand-angle / Principal)"}),' : La cam\xe9ra "normale" par d\xe9faut sur chaque t\xe9l\xe9phone. Champ de vision de ~75\xb0, similaire \xe0 la vision p\xe9riph\xe9rique humaine mais plus plat.']}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"45\u201380 mm (T\xe9l\xe9objectif, 2\xd7 \xe0 3\xd7)"})," : Champ de vision \xe9troit de 30\xb0 \xe0 50\xb0. Utilis\xe9 pour les portraits (proportions de visage d'aspect naturel, moins de distorsion de perspective) et le zoom g\xe9n\xe9ral."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"100\u2013240 mm (T\xe9l\xe9objectif p\xe9riscope, 5\xd7 \xe0 10\xd7)"})," : Champ de vision de 10\xb0 \xe0 25\xb0. La conception du p\xe9riscope \xe0 prisme courb\xe9 permet de longues distances focales sans que le t\xe9l\xe9phone ne fasse 2 centim\xe8tres d'\xe9paisseur."]}),"\n"]}),"\n",(0,i.jsx)(r.p,{children:"Voici comment la lumi\xe8re traverse un assemblage d'objectif grand-angle typique \xe0 5 \xe9l\xe9ments :"}),"\n",(0,i.jsx)(r.mermaid,{value:'graph LR\n    A["Rayons lumineux entrants"] --\x3e B["\xc9l\xe9ment 1<br/>Asph\xe9rique<br/>Convexe"]\n    B --\x3e C[\xc9l\xe9ment 2<br/>Concave<br/>Correction chromatique]\n    C --\x3e D[\xc9l\xe9ment 3<br/>Convexe]\n    D --\x3e E[\xc9l\xe9ment 4<br/>Concave<br/>Contr\xf4le de la distorsion]\n    E --\x3e F[\xc9l\xe9ment 5<br/>Plan-convexe]\n    F --\x3e G[Plan focal<br/>Capteur d\'image]'}),"\n",(0,i.jsx)(r.h3,{id:"ouverture",children:"Ouverture"}),"\n",(0,i.jsxs)(r.p,{children:["L'ouverture est la taille de l'orifice par lequel passe la lumi\xe8re \xe0 l'int\xe9rieur de l'objectif. Elle est d\xe9crite par un ",(0,i.jsx)(r.strong,{children:"nombre f"})," (ou f-stop) : la distance focale divis\xe9e par le diam\xe8tre de l'ouverture. Un ",(0,i.jsx)(r.strong,{children:"nombre f plus petit signifie un trou plus large, ce qui signifie que plus de lumi\xe8re"})," atteint le capteur."]}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsx)(r.li,{children:"f/1.4 \xe0 f/1.8 : Ouverture tr\xe8s large. Cam\xe9ras principales des fleurons typiques. Excellente en basse lumi\xe8re."}),"\n",(0,i.jsx)(r.li,{children:"f/2.0 \xe0 f/2.4 : Ouverture mod\xe9r\xe9e. Cam\xe9ras ultra-grand-angle et t\xe9l\xe9objectif typiques sur la plupart des t\xe9l\xe9phones."}),"\n",(0,i.jsx)(r.li,{children:"f/2.8 \xe0 f/4.0 : Ouverture \xe9troite. Pr\xe9sente sur les cam\xe9ras frontales \xe0 moindre co\xfbt et certains modules p\xe9riscope."}),"\n"]}),"\n",(0,i.jsxs)(r.p,{children:["L'ouverture est g\xe9n\xe9ralement fixe dans les cam\xe9ras de smartphone. Quelques fleurons Samsung des ann\xe9es 2020 disposaient d'un ",(0,i.jsx)(r.strong,{children:"m\xe9canisme d'ouverture variable"})," avec un double diaphragme qui pouvait basculer m\xe9caniquement entre f/1.5 et f/2.4. C'est extr\xeamement rare aujourd'hui car la mise au point bas\xe9e sur le VCM et le HDR computationnel multi-images ont rendu l'ouverture variable inutile pour la plupart des cas d'utilisation."]}),"\n",(0,i.jsx)(r.h3,{id:"stabilisation-optique-de-limage-ois",children:"Stabilisation optique de l'image (OIS)"}),"\n",(0,i.jsxs)(r.p,{children:["Lorsque vous tenez un t\xe9l\xe9phone, vos mains tremblent naturellement de minuscules quantit\xe9s angulaires \u2014 de l'ordre de 0,1\xb0 \xe0 0,5\xb0 \xe0 1/30e de seconde. Sur une exposition suffisamment longue, ce tremblement rend toute l'image floue. La ",(0,i.jsx)(r.strong,{children:"stabilisation optique de l'image (OIS)"})," r\xe9sout ce probl\xe8me en d\xe9pla\xe7ant physiquement soit le barillet de l'objectif (OIS par d\xe9calage de lentille), soit la puce du capteur elle-m\xeame (OIS par d\xe9calage de capteur) pour contrecarrer le mouvement d\xe9tect\xe9. Un minuscule gyroscope \xe0 l'int\xe9rieur du module cam\xe9ra (ou partag\xe9 avec l'IMU principal du t\xe9l\xe9phone) mesure la vitesse angulaire 1 000 \xe0 8 000 fois par seconde, et l'actionneur OIS d\xe9place l'optique en cons\xe9quence. L'OIS peut g\xe9n\xe9ralement compenser 3 \xe0 5 paliers de tremblement de la main, ce qui signifie qu'une exposition qui aurait n\xe9cessit\xe9 1/60s pour rester nette peut maintenant \xeatre prise \xe0 1/8s ou 1/4s avec une nettet\xe9 \xe9gale."]}),"\n",(0,i.jsx)(r.h2,{id:"le-capteur-dimage--l\xe0-o\xf9-la-lumi\xe8re-devient-\xe9lectricit\xe9",children:"Le capteur d'image : L\xe0 o\xf9 la lumi\xe8re devient \xe9lectricit\xe9"}),"\n",(0,i.jsxs)(r.p,{children:["Le capteur d'image est une puce en silicium contenant des millions de d\xe9tecteurs de lumi\xe8re individuels appel\xe9s ",(0,i.jsx)(r.strong,{children:"photodiodes"}),", dispos\xe9s dans une matrice rectangulaire pr\xe9cise. Chaque capteur de smartphone aujourd'hui est de type ",(0,i.jsx)(r.strong,{children:"CMOS (Complementary Metal-Oxide-Semiconductor)"}),"."]}),"\n",(0,i.jsx)(r.h3,{id:"taille-des-pixels-et-m\xe9gapixels",children:"Taille des pixels et m\xe9gapixels"}),"\n",(0,i.jsxs)(r.p,{children:["Chaque photodiode individuelle + son circuit de lecture est appel\xe9 un ",(0,i.jsx)(r.strong,{children:"pixel"}),". La taille physique de chaque pixel (mesur\xe9e en microm\xe8tres, \u03bcm) est sans doute plus importante que le nombre total de m\xe9gapixels. Un pixel plus grand capte plus de photons par unit\xe9 de temps, ce qui signifie moins de bruit de grenaille et de meilleures performances en basse lumi\xe8re."]}),"\n",(0,i.jsx)(r.p,{children:"Tailles de pixels courantes dans les smartphones de 2026 :"}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"0,6 \u03bcm \xe0 0,8 \u03bcm"})," : Tr\xe8s petits pixels. Utilis\xe9s dans les capteurs haute r\xe9solution de 108 MP \xe0 200 MP. Ceux-ci d\xe9pendent enti\xe8rement du regroupement de pixels (pixel binning) pour un bruit acceptable."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"1,0 \u03bcm \xe0 1,2 \u03bcm"})," : Taille moyenne. Utilis\xe9s dans les capteurs de 48 MP \xe0 64 MP avec un regroupement 4:1 par d\xe9faut pour une sortie de 12 MP \xe0 16 MP."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"2,0 \u03bcm \xe0 2,4 \u03bcm"}),' : Grands pixels "phare". Utilis\xe9s dans les capteurs d\xe9di\xe9s de 12 MP \xe0 16 MP (Google Pixel, iPhone Pro) ou comme sortie regroup\xe9e des capteurs de 48 MP en mode "haute qualit\xe9".']}),"\n"]}),"\n",(0,i.jsx)(r.p,{children:"Le regroupement de pixels (pixel binning) est la technique consistant \xe0 combiner la charge de pixels 2\xd72 (ou 3\xd73, ou 4\xd74) adjacents en un seul \"super pixel\" pendant la lecture. Un capteur de 48 MP avec des pixels individuels de 0,8 \u03bcm, lorsqu'il est regroup\xe9 4 pour 1, se comporte comme un capteur de 12 MP avec des pixels effectifs de 1,6 \u03bcm \u2014 am\xe9liorant consid\xe9rablement le rapport signal/bruit. L'API Camera2 expose \xe0 la fois le mode brut \xe0 pleine r\xe9solution et le mode regroup\xe9 par d\xe9faut comme des configurations de flux distinctes."}),"\n",(0,i.jsx)(r.p,{children:"Le calcul du nombre de m\xe9gapixels est simple : un capteur de 48 MP a une matrice active d'environ 8 000 \xd7 6 000 photodiodes = 48 000 000 de capteurs de lumi\xe8re individuels."}),"\n",(0,i.jsx)(r.h3,{id:"classifications-de-la-taille-du-capteur",children:"Classifications de la taille du capteur"}),"\n",(0,i.jsx)(r.p,{children:'La taille du capteur suit une notation h\xe9rit\xe9e bas\xe9e sur les pouces, remontant aux tubes de t\xe9l\xe9vision Vidicon des ann\xe9es 1950. Le format est "1/X pouce" o\xf9 X est le diviseur ; un X plus petit signifie un capteur plus grand :'}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsx)(r.li,{children:'1/3,06" \xe0 1/2,55" : Petits capteurs, typiques pour les cam\xe9ras frontales et les ultra-grand-angles d\'entr\xe9e de gamme (~5 MP \xe0 13 MP).'}),"\n",(0,i.jsx)(r.li,{children:'1/1,7" \xe0 1/1,3" : Grands capteurs mobiles, cam\xe9ras principales des fleurons (48 MP, 50 MP, 108 MP).'}),"\n",(0,i.jsx)(r.li,{children:"1 pouce (Type 1) : Tr\xe8s grand pour un t\xe9l\xe9phone. Pr\xe9sent dans le Xiaomi 13 Ultra, la s\xe9rie Sharp Aquos R et le Sony Xperia Pro-I. Surface active d'environ 13,2 mm \xd7 8,8 mm \u2014 proche de la taille de certains appareils photo Micro Four Thirds."}),"\n"]}),"\n",(0,i.jsx)(r.p,{children:"Un capteur plus grand, \xe0 nombre de m\xe9gapixels \xe9gal, poss\xe8de toujours des pixels individuels plus grands. C'est pourquoi les t\xe9l\xe9phones \xe0 \"capteur d'un pouce\" produisent des photos nettement meilleures en basse lumi\xe8re."}),"\n",(0,i.jsx)(r.h3,{id:"la-matrice-de-filtres-color\xe9s-bayer-cfa",children:"La matrice de filtres color\xe9s Bayer (CFA)"}),"\n",(0,i.jsxs)(r.p,{children:["Une photodiode en silicium brut est daltonienne \u2014 elle ne mesure que l'intensit\xe9 totale des photons, pas la longueur d'onde. Pour enregistrer la couleur, les fabricants d\xe9posent un minuscule ",(0,i.jsx)(r.strong,{children:"filtre color\xe9"})," sur chaque pixel individuel. Le motif presque universel est la ",(0,i.jsx)(r.strong,{children:"matrice de filtres Bayer RGGB"})," : 50 % de pixels verts, 25 % de rouges et 25 % de bleus, dispos\xe9s dans un carreau 2\xd72 r\xe9p\xe9titif. L'\u0153il humain est plus sensible \xe0 la lumi\xe8re verte, donc doubler l'\xe9chantillonnage vert am\xe9liore la r\xe9solution de luminance per\xe7ue et les performances en mati\xe8re de bruit."]}),"\n",(0,i.jsx)(r.mermaid,{value:'graph LR\n    subgraph "Motif Bayer 4x4 (RGGB)"\n        direction TB\n        A1[R] --- A2[G] --- A3[R] --- A4[G]\n        B1[G] --- B2[B] --- B3[G] --- B4[B]\n        C1[R] --- C2[G] --- C3[R] --- C4[G]\n        D1[G] --- D2[B] --- D3[G] --- D4[B]\n    end\n    E["Filtre anti-IR<br/>Bloque les infrarouges"] --\x3e F["Matrice de filtres color\xe9s<br/>Bayer RGGB d\xe9pos\xe9 sur le verre"]\n    F --\x3e G[Photodiodes en silicium<br/>Convertissent Photons\u2192\xc9lectrons]'}),"\n",(0,i.jsxs)(r.p,{children:["Apr\xe8s lecture, les donn\xe9es du capteur sont une mosa\xefque de valeurs s\xe9par\xe9es de rouge, vert et bleu \u2014 pas encore une image en couleur r\xe9elle. L'\xe9tape qui compl\xe8te les informations de couleur manquantes pour chaque pixel s'appelle le ",(0,i.jsx)(r.strong,{children:"d\xe9matri\xe7age"})," (ou debayering) et c'est la premi\xe8re \xe9tape de calcul majeure effectu\xe9e dans l'ISP."]}),"\n",(0,i.jsx)(r.h3,{id:"obturateur-roulant-vs-obturateur-global",children:"Obturateur roulant vs obturateur global"}),"\n",(0,i.jsxs)(r.p,{children:["Presque tous les capteurs d'image de smartphone utilisent un ",(0,i.jsx)(r.strong,{children:"obturateur roulant"})," (rolling shutter). Le capteur n'expose pas et ne lit pas tous les pixels en m\xeame temps. Au lieu de cela, il expose et lit la matrice de pixels ligne par ligne, de haut en bas, une ligne horizontale \xe0 la fois. La lecture roulante d'un capteur typique de 48 MP prend environ 15 \xe0 25 millisecondes pour une capture plein format."]}),"\n",(0,i.jsx)(r.p,{children:"L'obturateur roulant produit des distorsions caract\xe9ristiques sur les sujets se d\xe9pla\xe7ant tr\xe8s rapidement : une h\xe9lice d'avion en rotation ou un ventilateur de plafond semble courb\xe9 ou ondul\xe9 ; le haut et le bas d'un b\xe2timent panoramiqu\xe9 verticalement penchent dans des directions oppos\xe9es (l'effet \"jello\" en vid\xe9o). Les capteurs \xe0 obturateur global, en revanche, exposent chaque pixel simultan\xe9ment et les lisent tous en m\xeame temps apr\xe8s la fin de l'exposition. L'obturateur global est utilis\xe9 dans la vision industrielle, les cam\xe9ras d'action et certains capteurs sp\xe9cialis\xe9s de d\xe9verrouillage facial infrarouge orient\xe9s vers l'avant, mais la conception des pixels \xe0 obturateur global pr\xe9sente une sensibilit\xe9 \xe0 la lumi\xe8re plus faible et un co\xfbt plus \xe9lev\xe9, elle n'est donc pas utilis\xe9e dans les cam\xe9ras principales des smartphones."}),"\n",(0,i.jsx)(r.h2,{id:"lisp--processeur-de-signal-dimage",children:"L'ISP : Processeur de signal d'image"}),"\n",(0,i.jsxs)(r.p,{children:["L'",(0,i.jsx)(r.strong,{children:"ISP (Image Signal Processor)"})," est un bloc mat\xe9riel d\xe9di\xe9 (soit une puce s\xe9par\xe9e, soit, plus couramment aujourd'hui, une partie int\xe9gr\xe9e du SoC principal aux c\xf4t\xe9s du CPU et du GPU) dont le seul r\xf4le est de transformer les donn\xe9es brutes, mosa\xefqu\xe9es, bruit\xe9es et d\xe9form\xe9es provenant du capteur en une image couleur visuellement agr\xe9able."]}),"\n",(0,i.jsx)(r.p,{children:"L'ISP ex\xe9cute un pipeline fixe et c\xe2bl\xe9 d'\xe9tapes de traitement d'image \xe0 un d\xe9bit extr\xeamement \xe9lev\xe9. Un capteur moderne de 48 MP fonctionnant \xe0 30 images par seconde envoie 1,44 milliard de pixels par seconde \xe0 l'ISP. L'ISP doit traiter chaque pixel \xe0 travers toutes les \xe9tapes en moins de 33 millisecondes par image pour suivre le rythme."}),"\n",(0,i.jsx)(r.p,{children:"Les \xe9tapes canoniques du pipeline ISP, dans l'ordre, sont :"}),"\n",(0,i.jsxs)(r.ol,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Correction des pixels chauds"}),' : Les pixels "bloqu\xe9s" calibr\xe9s en usine (toujours clairs ou toujours sombres) sont remplac\xe9s par des valeurs interpol\xe9es des voisins.']}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"D\xe9matri\xe7age / Debayer"})," : La mosa\xefque Bayer RGGB est convertie en une image RVB compl\xe8te en estimant les deux canaux de couleur manquants \xe0 chaque emplacement de pixel \xe0 partir des pixels environnants \xe0 l'aide d'algorithmes d'interpolation sensibles aux contours."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"R\xe9duction du bruit (temporelle + spatiale)"})," : Le bruit de grenaille al\xe9atoire et le bruit de lecture du capteur sont supprim\xe9s. La r\xe9duction du bruit (NR) spatiale floute les r\xe9gions planes tout en pr\xe9servant les contours. La NR temporelle fusionne les informations des images vid\xe9o pr\xe9c\xe9dentes (si disponibles) pour des r\xe9sultats encore plus propres."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Correction de l'ombrage de l'objectif (Correction du vignettage)"})," : Les coins de l'image sont naturellement plus sombres car la lumi\xe8re doit traverser l'objectif \xe0 un angle plus prononc\xe9. L'ISP applique une rampe de gain num\xe9rique par pixel, plus lumineuse aux coins, pour aplatir l'\xe9clairage. Les donn\xe9es de calibration pour cette rampe sont stock\xe9es dans l'OTP du module."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Correction de la distorsion g\xe9om\xe9trique"})," : Les objectifs ultra-grand-angle et fisheye produisent une distorsion en barillet (les lignes droites se courbent vers l'ext\xe9rieur). L'ISP remappe les coordonn\xe9es des pixels \xe0 l'aide d'un mod\xe8le d'objectif polynomial stock\xe9 pour produire une image rectiligne o\xf9 les lignes droites apparaissent r\xe9ellement droites. Cette \xe9tape recadre intrins\xe8quement 5 \xe0 10 % de l'anneau de pixels ext\xe9rieur."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Matrice de correction des couleurs (CCM)"})," : La r\xe9ponse spectrale RVB du capteur brut ne correspond pas \xe0 la r\xe9ponse trichromatique de l'\u0153il humain. Une multiplication par une matrice 3\xd73 convertit le RVB natif du capteur en espace colorim\xe9trique standard sRVB ou DCI-P3. Les coefficients de la CCM sont ajust\xe9s par module et par illuminant (lumi\xe8re du jour, tungst\xe8ne, fluorescent)."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Ajustement de la courbe de tonalit\xe9"})," : Une courbe de mappage de tonalit\xe9 non lin\xe9aire en forme de S est appliqu\xe9e aux donn\xe9es RVB lin\xe9aires pour compresser le signal du capteur \xe0 plage dynamique \xe9lev\xe9e en une sortie \xe0 plage dynamique faible (g\xe9n\xe9ralement cod\xe9e en gamma sRVB 8 bits). C'est cette \xe9tape qui donne de l'\xe9clat \xe0 l'image \u2014 le contraste augmente dans les tons moyens, les zones lumineuses sont att\xe9nu\xe9es, les ombres sont rehauss\xe9es."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Am\xe9lioration des contours / Accentuation de la nettet\xe9"})," : Un masque flou subtil est appliqu\xe9 pour r\xe9cup\xe9rer les d\xe9tails haute fr\xe9quence att\xe9nu\xe9s par la r\xe9duction du bruit et le filtre optique passe-bas. La quantit\xe9 d'accentuation est soigneusement contr\xf4l\xe9e pour \xe9viter d'introduire des halos."]}),"\n"]}),"\n",(0,i.jsx)(r.mermaid,{value:'flowchart TD\n    A["Donn\xe9es Bayer brutes<br/>du capteur"] --\x3e B["Correction des pixels chauds"]\n    B --\x3e C[D\xe9matri\xe7age / Debayer<br/>Bayer \u2192 RVB complet]\n    C --\x3e D[R\xe9duction du bruit<br/>Spatiale + Temporelle]\n    D --\x3e E[Correction de l\'ombrage de l\'objectif<br/>Correction du vignettage]\n    E --\x3e F[Distorsion g\xe9om\xe9trique<br/>Correction fisheye / barillet]\n    F --\x3e G[Matrice de correction des couleurs<br/>Espace sRVB / P3]\n    G --\x3e H[Ajustement de la courbe de tonalit\xe9<br/>Gamma + Courbe en S]\n    H --\x3e I[Am\xe9lioration des contours / Accentuation]\n    I --\x3e J[Image finale trait\xe9e<br/>\u2192 Encodeur JPEG / Affichage]'}),"\n",(0,i.jsx)(r.p,{children:"La qualit\xe9 du traitement de l'ISP est un diff\xe9renciateur majeur entre les fabricants de t\xe9l\xe9phones. Google, Samsung, Apple et Xiaomi r\xe8glent chacun leurs pipelines ISP avec des priorit\xe9s artistiques diff\xe9rentes : certains privil\xe9gient les couleurs naturelles, d'autres une sortie satur\xe9e et percutante, d'autres encore une r\xe9duction agressive du bruit par rapport aux d\xe9tails conserv\xe9s. L'API Camera2 vous donne un certain contr\xf4le sur l'intensit\xe9 des \xe9tapes individuelles de l'ISP (via les commandes de mappage de tonalit\xe9 et de correction des couleurs d'Android), mais la plupart des param\xe8tres d'\xe9tape d\xe9taill\xe9s sont verrouill\xe9s derri\xe8re des API propri\xe9taires des fournisseurs."}),"\n",(0,i.jsx)(r.h2,{id:"raw-vs-jpeg--deux-chemins-du-capteur-au-stockage",children:"RAW vs JPEG : Deux chemins du capteur au stockage"}),"\n",(0,i.jsx)(r.p,{children:"Le pipeline ISP ci-dessus produit une image trait\xe9e. Mais l'API Camera2 vous permet \xe9galement de contourner enti\xe8rement l'ISP et de lire directement les donn\xe9es brutes du capteur. C'est la distinction critique entre la sortie RAW et JPEG."}),"\n",(0,i.jsx)(r.h3,{id:"format-raw",children:"Format RAW"}),"\n",(0,i.jsxs)(r.p,{children:["Un ",(0,i.jsx)(r.strong,{children:"fichier RAW"})," (sur Android, cela signifie un fichier DNG, Digital Negative) contient exactement ce que le capteur a mesur\xe9 avant tout traitement ISP. Il s'agit d'une mosa\xefque Bayer de 10, 12 ou 14 bits par pixel \u2014 toujours dans le motif RGGB original, toujours avec du vignettage, toujours avec du bruit, toujours lin\xe9aire. Le fichier RAW contient \xe9galement des balises de m\xe9tadonn\xe9es sp\xe9cifiant le motif exact de la matrice de filtres color\xe9s, le profil de couleur du capteur, le niveau de noir, le niveau de blanc et le mod\xe8le d'objectif."]}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Profondeur de bits"})," : RAW10 = 10 bits par canal = 1 024 niveaux. RAW12 = 4 096 niveaux. RAW14 = 16 384 niveaux. Comparez cela aux 8 bits du JPEG = 256 niveaux."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Taille du fichier"})," : 20 \xe0 40 Mo par photo de 48 MP. Non compress\xe9 ou compress\xe9 presque sans perte."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Cas d'utilisation"}),' : \xc9dition post-production professionnelle. Les paliers de dynamique suppl\xe9mentaires permettent \xe0 un \xe9diteur de "sauver" des zones lumineuses surexpos\xe9es (de 2 \xe0 3 paliers d\'EV) ou de rehausser des ombres sous-expos\xe9es sans effet de bande (banding).']}),"\n"]}),"\n",(0,i.jsx)(r.h3,{id:"format-jpeg",children:"Format JPEG"}),"\n",(0,i.jsxs)(r.p,{children:["Un ",(0,i.jsx)(r.strong,{children:"fichier JPEG"})," est la sortie enti\xe8rement \"cuite\" de l'ISP. Chacune des 8 \xe9tapes de l'ISP ci-dessus a d\xe9j\xe0 \xe9t\xe9 appliqu\xe9e aux donn\xe9es de pixels. Ensuite, l'image est convertie de RVB en espace colorim\xe9trique YCbCr 4:2:0 avec sous-\xe9chantillonnage de la chrominance et compress\xe9e avec un algorithme de transform\xe9e en cosinus discr\xe8te avec perte \xe0 un rapport de compression d'environ 10:1 \xe0 20:1."]}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Profondeur de bits"})," : Toujours 8 bits par canal = 256 niveaux par couleur."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Taille du fichier"})," : 2 \xe0 5 Mo pour une photo de 12 MP \xe0 48 MP, selon le niveau de qualit\xe9 JPEG."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Cas d'utilisation"}),' : Partage instantan\xe9, r\xe9seaux sociaux, tout flux de travail o\xf9 la photo est "termin\xe9e" d\xe8s la prise de vue. Les ajustements dans un \xe9diteur mobile d\xe9gradent rapidement l\'image car il ne reste que 256 niveaux.']}),"\n"]}),"\n",(0,i.jsx)(r.h3,{id:"tableau-de-comparaison--raw-vs-jpeg",children:"Tableau de comparaison : RAW vs JPEG"}),"\n",(0,i.jsxs)(r.table,{children:[(0,i.jsx)(r.thead,{children:(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.th,{children:"Caract\xe9ristique"}),(0,i.jsx)(r.th,{children:"RAW (DNG)"}),(0,i.jsx)(r.th,{children:"JPEG"})]})}),(0,i.jsxs)(r.tbody,{children:[(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Traitement ISP appliqu\xe9"}),(0,i.jsx)(r.td,{children:"Aucun \u2014 toutes les \xe9tapes ignor\xe9es"}),(0,i.jsx)(r.td,{children:"Les 8 \xe9tapes appliqu\xe9es et irr\xe9versibles"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Profondeur de couleur"}),(0,i.jsx)(r.td,{children:"10\u201314 bits (1 024\u201316 384 niveaux)"}),(0,i.jsx)(r.td,{children:"8 bits (256 niveaux)"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Balance des blancs"}),(0,i.jsx)(r.td,{children:"\xc9tiquet\xe9e dans les m\xe9tadonn\xe9es, modifiable en post"}),(0,i.jsx)(r.td,{children:"Incrust\xe9e dans les pixels \u2014 modifs mineures seulement"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Latitude d'exposition"}),(0,i.jsx)(r.td,{children:"\xb12 \xe0 3 paliers r\xe9cup\xe9rables"}),(0,i.jsx)(r.td,{children:"\xb11/2 palier au mieux avant effet de bande"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Taille du fichier (48 MP)"}),(0,i.jsx)(r.td,{children:"25\u201340 Mo"}),(0,i.jsx)(r.td,{children:"3\u20136 Mo"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Espace colorim\xe9trique"}),(0,i.jsx)(r.td,{children:"RVB lin\xe9aire natif du capteur"}),(0,i.jsx)(r.td,{children:"sRVB ou Display P3 encod\xe9 en gamma"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Nettet\xe9 / R\xe9duction du bruit"}),(0,i.jsx)(r.td,{children:"Aucune \u2014 choix de l'\xe9diteur"}),(0,i.jsx)(r.td,{children:"Appliqu\xe9e ; ne peut \xeatre annul\xe9e"})]}),(0,i.jsxs)(r.tr,{children:[(0,i.jsx)(r.td,{children:"Flux de travail typique"}),(0,i.jsx)(r.td,{children:"Adobe Lightroom / Capture One"}),(0,i.jsx)(r.td,{children:"Partage direct sur Instagram / Messages"})]})]})]}),"\n",(0,i.jsx)(r.h2,{id:"t\xe9l\xe9phones-multi-cam\xe9ras--pourquoi-pas-un-seul-zoom-g\xe9ant-",children:"T\xe9l\xe9phones multi-cam\xe9ras : Pourquoi pas un seul zoom g\xe9ant ?"}),"\n",(0,i.jsx)(r.p,{children:"Un appareil photo compact traditionnel utilise un seul zoom avec des groupes internes mobiles qui modifient continuellement la distance focale du grand-angle au t\xe9l\xe9objectif. Pourquoi un smartphone ne peut-il pas faire la m\xeame chose ? La physique. Un zoom 10\xd7 qui couvre l'\xe9quivalent plein format 24 mm\u2013240 mm avec une ouverture constante de f/2.8 n\xe9cessite un chemin optique d'environ 5 centim\xe8tres (2 pouces) de long. Un smartphone mesure, au plus, 0,9 centim\xe8tre d'\xe9paisseur. Le calcul ne correspond tout simplement pas."}),"\n",(0,i.jsxs)(r.p,{children:["L'industrie du smartphone a r\xe9solu ce probl\xe8me non pas avec un zoom, mais avec ",(0,i.jsx)(r.strong,{children:"plusieurs cam\xe9ras \xe0 distance focale fixe"}),", chacune optimis\xe9e pour un usage diff\xe9rent, et un syst\xe8me de \"zoom fluide\" computationnel qui passe d'une cam\xe9ra \xe0 l'autre \xe0 des rapports de zoom sp\xe9cifiques."]}),"\n",(0,i.jsx)(r.p,{children:"Un \xeelot de cam\xe9ras arri\xe8re typique d'un fleuron de 2026 contient :"}),"\n",(0,i.jsxs)(r.ol,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Ultra-grand-angle (zoom 0,5\xd7, ~13 mm \xe9q, ~120\xb0 FOV)"})," : Courte distance focale, grande profondeur de champ. Id\xe9al pour les paysages, l'architecture, les photos de groupe et la macro de pr\xe8s lorsqu'il est repositionn\xe9 via le logiciel."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Grand-angle / Principal (zoom 1\xd7, ~24 mm \xe9q, ~75\xb0 FOV)"})," : Le choix par d\xe9faut. Le plus grand capteur, l'ouverture la plus large, le meilleur OIS. Utilis\xe9 pour 80 % des photos quotidiennes."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"T\xe9l\xe9objectif / P\xe9riscope (optique 3\xd7 \xe0 10\xd7, ~72 mm \xe0 ~240 mm \xe9q)"})," : Un t\xe9l\xe9objectif conventionnel (3\xd7) se trouve directement au-dessus de son capteur. Un t\xe9l\xe9objectif p\xe9riscope (5\xd7, 10\xd7) utilise un prisme \xe0 45\xb0 pr\xe8s du bord du t\xe9l\xe9phone pour r\xe9fl\xe9chir la lumi\xe8re \xe0 90\xb0, de sorte que le barillet de l'objectif court horizontalement \xe0 l'int\xe9rieur du corps du t\xe9l\xe9phone plut\xf4t que verticalement \xe0 travers son \xe9paisseur."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"Capteur ToF / Profondeur"})," : Un projecteur de points laser proche infrarouge (ou, sur les iPhone, un scanner LiDAR \xe0 lumi\xe8re structur\xe9e) qui projette plus de 30 000 points IR sur la sc\xe8ne et mesure leur temps de trajet aller-retour pour produire une carte de profondeur par pixel. Utilis\xe9 pour un bokeh de portrait pr\xe9cis, l'occlusion en r\xe9alit\xe9 augment\xe9e et une mise au point automatique rapide en basse lumi\xe8re."]}),"\n"]}),"\n",(0,i.jsx)(r.mermaid,{value:'graph TB\n    subgraph "\xcelot cam\xe9ra arri\xe8re du t\xe9l\xe9phone"\n        A["Vitre de protection arri\xe8re"]\n    end\n    A --\x3e B[Cam\xe9ra ultra-grand-angle<br/>13 mm \xe9q / 120\xb0 FOV]\n    A --\x3e C[Cam\xe9ra grand-angle / principale<br/>24 mm \xe9q / f/1.6 + OIS]\n    A --\x3e D[T\xe9l\xe9objectif p\xe9riscope 5\xd7<br/>120 mm \xe9q / R\xe9fraction par prisme]\n    A --\x3e E[Capteur de profondeur ToF<br/>Projecteur de points laser]'}),"\n",(0,i.jsx)(r.p,{children:"Lorsque vous effectuez un geste de pincement pour zoomer dans l'application cam\xe9ra, le HAL (Hardware Abstraction Layer) bascule en douceur la cam\xe9ra physique active \xe0 des seuils pr\xe9d\xe9termin\xe9s. Par exemple, zoomer de 0,5\xd7 \xe0 1,0\xd7 passe de l'ultra-grand-angle au grand-angle. \xc0 2,9\xd7, l'application effectue toujours un recadrage num\xe9rique de la cam\xe9ra grand-angle. \xc0 3,0\xd7, le HAL bascule la source active vers la cam\xe9ra t\xe9l\xe9objectif p\xe9riscope. Entre ces rapports de zoom, un algorithme sophistiqu\xe9 de fusion d'images utilise les deux cam\xe9ras simultan\xe9ment pour maintenir une transition fluide."}),"\n",(0,i.jsx)(r.h2,{id:"le-voyage-complet--du-photon-\xe0-la-photo-enregistr\xe9e-milliseconde-par-milliseconde",children:"Le voyage complet : Du photon \xe0 la photo enregistr\xe9e, milliseconde par milliseconde"}),"\n",(0,i.jsx)(r.p,{children:"Voici la chronologie compl\xe8te et num\xe9rot\xe9e de ce qui se passe physiquement \xe0 l'int\xe9rieur d'un smartphone lors d'une seule capture de photo fixe, \xe0 partir du moment o\xf9 le doigt de l'utilisateur quitte le bouton d'obturateur virtuel. Les chiffres sont repr\xe9sentatifs d'un fleuron de 2026 capturant un JPEG en mode par d\xe9faut 12 MP en plein jour :"}),"\n",(0,i.jsxs)(r.ul,{children:["\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"0 ms"})," : L'utilisateur appuie sur l'obturateur. Le framework de l'API Camera2 re\xe7oit la ",(0,i.jsx)(r.code,{children:"CaptureRequest"})," avec ",(0,i.jsx)(r.code,{children:"TEMPLATE_STILL_CAPTURE"}),"."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"0\u20132 ms"})," : L'algorithme 3A (Auto-Focus, Auto-Exposure, Auto-White-Balance) converge vers ses valeurs finales."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"2\u20136 ms"})," : Le moteur \xe0 bobine mobile (VCM) excite sa bobine, d\xe9pla\xe7ant physiquement le barillet de l'objectif de 0,2 mm \xe0 la distance de mise au point exacte calcul\xe9e par l'algorithme AF."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"6\u201321 ms (exposition de 15 ms)"})," : La r\xe9initialisation globale lib\xe8re la charge des pixels du capteur. Pendant 15 millisecondes, les photodiodes accumulent des \xe9lectrons g\xe9n\xe9r\xe9s par les photons. L'obturateur roulant lit ligne par ligne pendant et apr\xe8s cette fen\xeatre."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"18\u201328 ms"})," : Le capteur envoie les donn\xe9es Bayer brutes via le bus s\xe9rie haute vitesse MIPI CSI-2. Une configuration typique comporte 4 voies de donn\xe9es \xe0 2,5 Gbps par voie = 10 Gbps de bande passante totale, ce qui g\xe8re confortablement la profondeur de bits brute d'une image de 12 MP plus les intervalles de suppression."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"28\u201331 ms"})," : Le pipeline \xe0 8 \xe9tapes de l'ISP traite l'image : correction des pixels chauds, d\xe9matri\xe7age, r\xe9duction du bruit, ombrage de l'objectif, correction g\xe9om\xe9trique, matrice de couleurs, courbe de tonalit\xe9 et accentuation. Cela se passe enti\xe8rement au niveau mat\xe9riel \u2014 aucune intervention du CPU au niveau des pixels."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"31\u201333 ms"})," : L'image YUV trait\xe9e est envoy\xe9e \xe0 l'encodeur JPEG mat\xe9riel, qui applique une compression DCT avec perte au niveau de qualit\xe9 90\u201395 et \xe9crit les en-t\xeates de fichier JFIF (EXIF, vignette, coordonn\xe9es GPS si marqu\xe9es)."]}),"\n",(0,i.jsxs)(r.li,{children:[(0,i.jsx)(r.strong,{children:"33\u201340 ms"})," : Le bloc JPEG termin\xe9 est \xe9crit via le fournisseur de contenu MediaStore dans le r\xe9pertoire des fichiers de l'application, par exemple ",(0,i.jsx)(r.code,{children:"/data/data/com.votrepaquet/files/DCIM/Camera/IMG_20260806_151042.jpg"}),". Le MediaScanner est notifi\xe9 et la photo appara\xeet dans la galerie du syst\xe8me."]}),"\n"]}),"\n",(0,i.jsx)(r.mermaid,{value:"sequenceDiagram\n    participant User\n    participant UI as App UI\n    participant VCM as VCM / Actionneur mise au point\n    participant Sensor as Capteur d'image\n    participant MIPI as Bus MIPI CSI-2\n    participant ISP as Pipeline ISP\n    participant JPEG as Encodeur JPEG\n    participant Storage as Stockage Flash\n\n    User->>UI: 0ms: Appui sur le bouton d'obturateur\n    UI->>VCM: 2ms: D\xe9placement de l'objectif \xe0 la distance AF\n    VCM--\x3e>UI: 6ms: Mise au point verrouill\xe9e\n    UI->>Sensor: 6ms: D\xe9but de l'exposition\n    Note over Sensor: 6ms\u201321ms: Exposition 15ms lecture roulante\n    Sensor->>MIPI: 18ms\u201328ms: Flux RAW Bayer @ 10Gbps\n    MIPI->>ISP: 28ms: Image compl\xe8te re\xe7ue\n    Note over ISP: 28ms\u201331ms: Traitement pipeline 8 \xe9tapes\n    ISP->>JPEG: 31ms: Envoi de l'image YUV\n    JPEG--\x3e>ISP: 33ms: JPEG compress\xe9\n    ISP->>Storage: 33ms\u201340ms: \xc9criture JPEG + EXIF\n    Storage--\x3e>UI: 40ms: Fichier enregistr\xe9 OK\n    UI--\x3e>User: 40ms: Affichage de l'animation de la vignette"}),"\n",(0,i.jsx)(r.p,{children:"L'ensemble du processus prend environ 40 millisecondes de bout en bout pour une photo fixe en plein jour. En basse lumi\xe8re, le temps d'exposition lui-m\xeame s'allonge (potentiellement jusqu'\xe0 plusieurs secondes pour une capture multi-images en mode Nuit), et la chronologie s'\xe9tire proportionnellement."}),"\n",(0,i.jsx)(r.h2,{id:"r\xe9sum\xe9",children:"R\xe9sum\xe9"}),"\n",(0,i.jsx)(r.p,{children:"Vous avez maintenant une image physique compl\xe8te du syst\xe8me de cam\xe9ra du smartphone. Vous savez que chaque bosse de cam\xe9ra arri\xe8re est un module scell\xe9 contenant un barillet d'objectif \xe0 plusieurs \xe9l\xe9ments, un actionneur de mise au point automatique VCM, un filtre anti-IR, un capteur CMOS avec une matrice de filtres color\xe9s Bayer RGGB et un c\xe2ble flexible transportant des donn\xe9es MIPI CSI-2. Vous comprenez la distance focale \xe9quivalente, l'ouverture et l'OIS. Vous savez comment le pipeline \xe0 8 \xe9tapes de l'ISP transforme une mosa\xefque Bayer brute en un JPEG fini, et vous pouvez distinguer le RAW (natif du capteur, 10\u201314 bits, marge de post-traitement) du JPEG (trait\xe9 par l'ISP, 8 bits, pr\xeat \xe0 partager). Vous comprenez pourquoi les t\xe9l\xe9phones modernes utilisent plus de 3 cam\xe9ras fixes au lieu d'un zoom, et vous avez parcouru la chronologie exacte, milliseconde par milliseconde, d'une seule capture photo."}),"\n",(0,i.jsx)(r.h2,{id:"et-ensuite-",children:"Et ensuite ?"}),"\n",(0,i.jsx)(r.p,{children:"Dans le chapitre 3, nous passerons du mat\xe9riel physique \xe0 ce que ce mat\xe9riel est capable de produire. Nous explorerons les fonctionnalit\xe9s r\xe9elles de la photographie moderne sur smartphone : le bracketing multi-images HDR, le bokeh de portrait via st\xe9r\xe9o / ToF / ML, les longues expositions multi-images Night Sight, la capture vid\xe9o haute vitesse au ralenti, la correction de distorsion ultra-grand-angle et le zoom p\xe9riscope. Vous apprendrez comment la photographie computationnelle \u2014 la fusion de l'optique, des capteurs, du traitement du signal multi-images et de l'apprentissage automatique sur l'appareil \u2014 cr\xe9e des images qu'aucune combinaison objectif/capteur unique ne pourrait jamais produire seule."})]})}function c(e={}){const{wrapper:r}={...(0,t.R)(),...e.components};return r?(0,i.jsx)(r,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,r,s){s.d(r,{R:()=>a,x:()=>l});var n=s(6540);const i={},t=n.createContext(i);function a(e){const r=n.useContext(t);return n.useMemo(function(){return"function"==typeof e?e(r):{...r,...e}},[r,e])}function l(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:a(e.components),n.createElement(t.Provider,{value:r},e.children)}}}]);